"""Wait policies for rollup partition mappers."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional


@dataclass(frozen=True)
class PartitionSatisfaction:
    """
    Result of evaluating a :class:`WaitPolicy` against a set of partition keys.

    ``satisfied`` reports whether the wait policy fires (a Dag run should be
    created). ``unreachable`` reports whether the policy can *never* be
    satisfied given the window's cardinality; when it is ``True``,
    ``unreachable_reason`` must carry a human-readable explanation, and when it
    is ``False`` the reason must be ``None`` — the constructor enforces this
    invariant so callers never see a half-populated result.
    """

    satisfied: bool
    unreachable: bool = False
    unreachable_reason: Optional[str] = field(default=None)

    def __post_init__(self) -> None:
        if self.unreachable and self.unreachable_reason is None:
            raise ValueError("unreachable_reason must be set when unreachable=True")
        if not self.unreachable and self.unreachable_reason is not None:
            raise ValueError("unreachable_reason must be None when unreachable=False")


class WaitPolicy(ABC):
    """
    Abstract base class for rollup wait policies.

    A wait policy decides, given the set of upstream partition keys that have
    arrived (``matched``) versus the full set the window expects
    (``expected``), whether the downstream rollup Dag run should fire. The
    default :meth:`is_satisfied_by_keys` converts the key sets to counts and
    delegates to :meth:`is_satisfied`; subclasses must implement
    :meth:`is_satisfied` and :meth:`is_unreachable`.
    """

    @abstractmethod
    def is_satisfied(self, matched: int, expected: int) -> bool:
        """Return whether ``matched`` arrived keys satisfy the policy for a window of ``expected`` keys."""

    @abstractmethod
    def is_unreachable(self, expected: int) -> bool:
        """Return whether the policy can never be satisfied given a window of ``expected`` keys."""

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        """
        Evaluate the policy against concrete key sets.

        Counts the keys that both arrived and are expected (the intersection),
        delegates the fire/hold decision to :meth:`is_satisfied`, and reports
        whether the policy is permanently unreachable for this window.
        """
        expected_count = len(expected)
        matched_count = len(matched & expected)
        satisfied = self.is_satisfied(matched_count, expected_count)
        if self.is_unreachable(expected_count):
            reason = (
                f"wait policy {self!r} can never be satisfied given the window's "
                f"cardinality {expected_count}"
            )
            return PartitionSatisfaction(satisfied=satisfied, unreachable=True, unreachable_reason=reason)
        return PartitionSatisfaction(satisfied=satisfied, unreachable=False, unreachable_reason=None)


class WaitForAll(WaitPolicy):
    """Fire only when every expected partition key has arrived."""

    def __repr__(self) -> str:
        return "WaitForAll()"

    def __eq__(self, other: object) -> bool:
        return type(other).__name__ == "WaitForAll"

    def __hash__(self) -> int:
        return hash("WaitForAll")

    def is_satisfied(self, matched: int, expected: int) -> bool:
        return matched == expected

    def is_unreachable(self, expected: int) -> bool:
        return False

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        if matched >= expected:
            return PartitionSatisfaction(satisfied=True, unreachable=False, unreachable_reason=None)
        return super().is_satisfied_by_keys(matched, expected)


class MinimumCount(WaitPolicy):
    """
    Fire once a minimum number of upstream keys have arrived.

    A positive ``n`` fires when at least ``n`` keys have arrived. A negative
    ``n`` is relative to the window size: it fires when at least
    ``max(0, expected + n)`` keys have arrived (i.e. "all but ``-n``"). ``n=0``
    is degenerate (it would fire on an empty window) and is rejected.
    """

    def __init__(self, n: int) -> None:
        if n == 0:
            raise ValueError("MinimumCount(0) is degenerate; use a positive or negative non-zero count")
        self.n = n

    def __repr__(self) -> str:
        return f"MinimumCount(n={self.n})"

    def __eq__(self, other: object) -> bool:
        return type(other).__name__ == "MinimumCount" and getattr(other, "n", None) == self.n

    def __hash__(self) -> int:
        return hash(("MinimumCount", self.n))

    def is_satisfied(self, matched: int, expected: int) -> bool:
        if self.n > 0:
            return matched >= self.n
        return matched >= max(0, expected + self.n)

    def is_unreachable(self, expected: int) -> bool:
        return self.n > 0 and self.n > expected
